package com.aadil.ecommerce.controllers;import com.aadil.ecommerce.responses.APIResponse;import com.aadil.ecommerce.services.UserService;import lombok.RequiredArgsConstructor;import org.springframework.http.HttpStatus;import org.springframework.http.ResponseEntity;import org.springframework.validation.annotation.Validated;import org.springframework.web.bind.annotation.*;import java.time.LocalDateTime;@RestController@RequestMapping("/api/users")@Validated@RequiredArgsConstructorpublic class UserController {    private final UserService userService;    @PostMapping("/invitation-accept/{rawToken}")    public ResponseEntity<APIResponse<String>> invitationAccept (@PathVariable String rawToken){        String invitationAccept = userService.invitationAcceptance(rawToken);        APIResponse<String> apiResponse = new APIResponse<>();        apiResponse.setSuccess(true);        apiResponse.setCode(200);        apiResponse.setData(invitationAccept);        apiResponse.setTimeStamp(LocalDateTime.now());        return new ResponseEntity<>(apiResponse, HttpStatus.OK);    }}